function particles(x,z,color){if(!v.particles||bursts.length>=48)return;for(let i=0;i<3;i++){let o=ball('spark',.07,color,null,x,.5,z);o.isPickable=false;o.receiveShadows=false;shadows.removeShadowCaster(o);bursts.push({o,life:.45,max:.45,dx:Math.cos(i)*2,dz:Math.sin(i)*2,dy:2+i*.2});}}
function consumeEvents(){for(const e of sim.events){window.roundCircleAudio?.event(e);window.roundCircleLab?.features?.event(e);if(e.type==='wave-start')waveFeedback.trigger(e);if(e.type==='training-complete'||e.type==='training-started')window.roundCircleProduction?.event(e);if(e.type==='shot'&&bolts.length<40){let o=ball('shot',.12,e.hostile?red:light,null,e.from.x,.8,e.from.z);o.isPickable=false;o.receiveShadows=false;shadows.removeShadowCaster(o);bolts.push({o,life:.16,from:e.from,to:e.to});}if(e.type==='hit'){let r=renderers.get(e.id);if(r)r.hit=.18;}if(e.type==='death'||e.type==='ram')particles(e.x,e.z,red);if(e.type==='building-born'||e.type==='wagon-born')particles(e.x,e.z,light);if(e.type==='wagon-born')notice('Train plein : une maison a produit un nouveau wagon.');if(e.type==='spawn'){particles(e.x,e.z,light);vortexFx.burst();}}sim.events=[];}
function updateRender(dt){updateSky(dt);let entities=sim.all(),ids=new Set(entities.map(e=>e.id));for(const id of renderers.keys())if(!ids.has(id))clearRenderer(id);for(const e of entities){if((e.hp<=0||e.dead)&&['monster','actor'].includes(e.kind)){clearRenderer(e.id);continue;}let r=renderers.get(e.id)||makeEntity(e);if(e.hp<=0||e.dead){r.root.setEnabled(e.kind==='building'||e.kind==='train');r.root.scaling.y=.25;r.bar.style.display='none';continue;}r.root.setEnabled(true);r.root.scaling.setAll(1);let y=.11;if(e.kind==='actor'){if(e.wagonId){let w=sim.wagons.find(w=>w.id===e.wagonId);const index=sim.passengers(w).findIndex(a=>a.id===e.id),cols=2,rows=Math.ceil(w.capacity/cols),lx=(index%2-.5)*.36,lz=(Math.floor(index/2)-(rows-1)/2)*Math.min(.27,.85/Math.max(1,rows));let rot=-w.angle;r.root.position.set(w.x+lx*Math.cos(rot)+lz*Math.sin(rot),.56,w.z-lx*Math.sin(rot)+lz*Math.cos(rot));r.root.rotation.y=rot;}else{r.root.position.set(e.x,y+(v.animate?Math.abs(Math.sin(sim.time*8+e.id))*.055:0),e.z);r.root.rotation.y=-e.angle;}}else{r.root.position.set(e.x,y,e.z);r.root.rotation.y=e.kind==='building'?-e.angle+Math.PI/2:e.kind==='monster'?-e.angle-Math.PI/2:-e.angle;}
 if(e.kind==='monster'&&v.animate){if(r.limbs)r.limbs.forEach((limb,i)=>limb.rotation.z=Math.sin(sim.time*5+i)*.07);r.root.scaling.y=1+Math.sin(sim.time*5+e.id)*.11;r.root.rotation.z=Math.sin(sim.time*3+e.id)*.07;}if(presets[mode]?.breathing&&e.kind==='building'&&v.animate)r.root.scaling.y=1+Math.sin(sim.time*1.5+e.id)*.025;if(r.hit>0){r.hit-=dt;r.root.scaling.x=1.13;r.root.scaling.z=1.13;}
 }
 vortexFx.update(sim.time,sim.cfg.vortexRadius,dt,paused,v.particles);if(!paused){for(let i=bolts.length-1;i>=0;i--){let s=bolts[i];s.life-=dt;let t=1-s.life/.16;s.o.position.set(s.from.x+(s.to.x-s.from.x)*t,.8,s.from.z+(s.to.z-s.from.z)*t);if(s.life<=0){s.o.dispose();bolts.splice(i,1);}}for(let i=bursts.length-1;i>=0;i--){let p=bursts[i];p.life-=dt;p.o.position.addInPlace(new B.Vector3(p.dx*dt,p.dy*dt,p.dz*dt));p.dy-=8*dt;p.o.scaling.setAll(Math.max(0,p.life/p.max));if(p.life<=0){p.o.dispose();bursts.splice(i,1);}}}}
